/*
 * runtime.h - execution model for SAB2.COM code translated to C (the web
 * build). Included by src/runtime.c (hand-written parts) and
 * build/.../sab2_code.c (generated by tools/asm2c.py). The C counterpart of
 * runtime.inc.
 *
 * - The 8086 registers are the fields of the cpu struct (bios.h), so BIOS
 *   and port calls need no copying. AL/AH etc. alias their bytes (little
 *   endian host).
 * - CF, ZF, SF, OF, AF and DF are globals. PF is not modelled: no code reads
 *   it (no JP/JNP; LAHF and PUSHF images are only used for CF).
 * - ds / es are the host bases of DS / ES; seg_ds / seg_es their 16-bit values.
 *   CS is the constant 1000h.
 * - One stack of 32-bit entries holds PUSH values, CALL return offsets and
 *   the interrupt frames of the timer delivery. The one place the game saves
 *   and reloads SP (sound_seq_play) saves and reloads the stack index.
 * - pc is the CS offset of the next instruction. The generated game_run() is
 *   one switch with a case per instruction; every transfer sets pc.
 */
#ifndef SAB2_RUNTIME_H
#define SAB2_RUNTIME_H

#include "bios.h"

#define AX cpu.ax
#define BX cpu.bx
#define CX cpu.cx
#define DX cpu.dx
#define SI cpu.si
#define DI cpu.di
#define BP cpu.bp
#define AL (((uint8_t *)&cpu.ax)[0])
#define AH (((uint8_t *)&cpu.ax)[1])
#define BL (((uint8_t *)&cpu.bx)[0])
#define BH (((uint8_t *)&cpu.bx)[1])
#define CL (((uint8_t *)&cpu.cx)[0])
#define CH (((uint8_t *)&cpu.cx)[1])
#define DL (((uint8_t *)&cpu.dx)[0])
#define DH (((uint8_t *)&cpu.dx)[1])

#define STACK_ENTRIES 4096

extern uint8_t cf, zf, sf, of, af, df;
extern uint8_t *ds, *es;
extern uint16_t seg_ds, seg_es;
extern uint8_t ds_base[SEGMENT_SIZE];
extern uint32_t stack[STACK_ENTRIES];
extern unsigned sp;
extern uint32_t pc;

uint8_t *seg_to_base(uint16_t seg);
_Noreturn void stack_fault(void);
_Noreturn void divide_fault(uint32_t cs_offset);

/* TIMER_POLL points (asm2c.py): timer_poll_begin(wait) returns 1 when INT 1Ch
 * ticks are due (timer_due in bios.c) and saves the game's state; then each
 * timer_poll_next() that returns 1 has set up the registers for one call of
 * the installed handler at timer_vector, which the caller enters as an
 * interrupt (flags, return pc). The last one restores the state and returns 0. */
extern uint32_t timer_vector;
int timer_poll_begin(uint32_t wait);
int timer_poll_next(void);

/* The port's changes called from the generated code (see asm2c.py MARKERS_C). */
void port_save(void);
void port_restore(void);
void port_add_time(void);
void port_hold_keys(void);

/* Reads and clears a byte the main thread counts up (cheat presses). */
static inline uint8_t take_u8(volatile uint8_t *p)
{
    return __atomic_exchange_n(p, 0, __ATOMIC_SEQ_CST);
}

/* ------------------------------------------------------------------------ */
/* Memory: 16-bit offsets wrap inside the 64 KB segment. */

static inline uint16_t rd16(const uint8_t *b, uint16_t o)
{
    return (uint16_t)(b[o] | b[(uint16_t)(o + 1)] << 8);
}

static inline void wr16(uint8_t *b, uint16_t o, uint32_t v)
{
    b[o] = (uint8_t)v;
    b[(uint16_t)(o + 1)] = (uint8_t)(v >> 8);
}

static inline void push(uint32_t v)
{
    if (sp == STACK_ENTRIES)
        stack_fault();
    stack[sp++] = v;
}

static inline uint32_t pop(void)
{
    if (sp == 0)
        stack_fault();
    return stack[--sp];
}

static inline void set_ds(uint16_t v)
{
    seg_ds = v;
    ds = seg_to_base(v);
}

static inline void set_es(uint16_t v)
{
    seg_es = v;
    es = seg_to_base(v);
}

/* ------------------------------------------------------------------------ */
/* Arithmetic with 8086 flags; bits = 8 or 16. */

#define MASK(bits) ((bits) == 8 ? 0xFFu : 0xFFFFu)
#define SIGN(bits) ((bits) == 8 ? 0x80u : 0x8000u)

static inline uint32_t f_add(uint32_t a, uint32_t b, uint32_t c, int bits)
{
    uint32_t r = a + b + c, res = r & MASK(bits);
    cf = r > MASK(bits);
    zf = res == 0;
    sf = (res & SIGN(bits)) != 0;
    af = ((a ^ b ^ res) & 0x10) != 0;
    of = ((a ^ res) & (b ^ res) & SIGN(bits)) != 0;
    return res;
}

static inline uint32_t f_sub(uint32_t a, uint32_t b, uint32_t c, int bits)
{
    uint32_t res = (a - b - c) & MASK(bits);
    cf = a < b + c;
    zf = res == 0;
    sf = (res & SIGN(bits)) != 0;
    af = ((a ^ b ^ res) & 0x10) != 0;
    of = ((a ^ b) & (a ^ res) & SIGN(bits)) != 0;
    return res;
}

static inline uint32_t f_logic(uint32_t res, int bits)
{
    cf = of = af = 0;
    zf = res == 0;
    sf = (res & SIGN(bits)) != 0;
    return res;
}

static inline uint32_t f_inc(uint32_t a, int bits)
{
    uint8_t c = cf;
    uint32_t r = f_add(a, 1, 0, bits);
    cf = c;
    return r;
}

static inline uint32_t f_dec(uint32_t a, int bits)
{
    uint8_t c = cf;
    uint32_t r = f_sub(a, 1, 0, bits);
    cf = c;
    return r;
}

enum { SH_SHL, SH_SHR, SH_SAR, SH_ROL, SH_ROR, SH_RCL, SH_RCR };

/* Shifts and rotates. The count is masked to 5 bits as on the x86-64 host
 * the NASM build runs on; a zero count leaves value and flags unchanged. */
static inline uint32_t f_shift(int op, uint32_t v, uint32_t n, int bits)
{
    const uint32_t m = MASK(bits), s = SIGN(bits);
    n &= 31;
    if (n == 0)
        return v;
    switch (op) {
    case SH_SHL:
        v = (v << (n - 1)) & m;
        cf = (v & s) != 0;
        v = (v << 1) & m;
        of = ((v & s) != 0) ^ cf;
        break;
    case SH_SHR:
        of = (v & s) != 0;
        v >>= n - 1;
        cf = v & 1;
        v >>= 1;
        break;
    case SH_SAR:
        for (uint32_t i = 0; i < n; i++) {
            cf = v & 1;
            v = (v >> 1) | (v & s);
        }
        of = 0;
        break;
    case SH_ROL:
        for (uint32_t i = 0; i < n; i++) {
            cf = (v & s) != 0;
            v = ((v << 1) | cf) & m;
        }
        of = ((v & s) != 0) ^ cf;
        return v;
    case SH_ROR:
        for (uint32_t i = 0; i < n; i++) {
            cf = v & 1;
            v = (v >> 1) | (cf ? s : 0);
        }
        of = ((v ^ (v << 1)) & s) != 0;
        return v;
    case SH_RCL:
        for (uint32_t i = 0; i < n; i++) {
            uint8_t out = (v & s) != 0;
            v = ((v << 1) | cf) & m;
            cf = out;
        }
        of = ((v & s) != 0) ^ cf;
        return v;
    case SH_RCR:
        of = ((v & s) != 0) ^ cf;
        for (uint32_t i = 0; i < n; i++) {
            uint8_t out = v & 1;
            v = (v >> 1) | (cf ? s : 0);
            cf = out;
        }
        return v;
    }
    /* Shifts set ZF and SF from the result; rotates leave them. */
    zf = v == 0;
    sf = (v & s) != 0;
    return v;
}

static inline void f_mul8(uint8_t src)
{
    AX = (uint16_t)(AL * src);
    cf = of = AH != 0;
}

static inline void f_mul16(uint16_t src)
{
    uint32_t r = (uint32_t)AX * src;
    AX = (uint16_t)r;
    DX = (uint16_t)(r >> 16);
    cf = of = DX != 0;
}

/* DIV: a zero divisor or a quotient too large is a divide error (INT 0),
 * which the game never handles. */
static inline void f_div8(uint8_t src, uint32_t cs_offset)
{
    if (src == 0 || AX / src > 0xFF)
        divide_fault(cs_offset);
    uint16_t a = AX;
    AL = (uint8_t)(a / src);
    AH = (uint8_t)(a % src);
}

static inline void f_div16(uint16_t src, uint32_t cs_offset)
{
    uint32_t a = (uint32_t)DX << 16 | AX;
    if (src == 0 || a / src > 0xFFFF)
        divide_fault(cs_offset);
    AX = (uint16_t)(a / src);
    DX = (uint16_t)(a % src);
}

/* AAA as on the 8086 (see AAA16 in runtime.inc). */
static inline void f_aaa(void)
{
    if ((AL & 0x0F) > 9 || af) {
        AL += 6;
        AH += 1;
        af = cf = 1;
    } else {
        af = cf = 0;
    }
    AL &= 0x0F;
}

static inline uint16_t flags_image(void)
{
    return (uint16_t)(cf | 0x02 | af << 4 | zf << 6 | sf << 7 | df << 10 | of << 11);
}

static inline void set_flags_image(uint16_t f)
{
    cf = f & 1;
    af = (f >> 4) & 1;
    zf = (f >> 6) & 1;
    sf = (f >> 7) & 1;
    df = (f >> 10) & 1;
    of = (f >> 11) & 1;
}

/* LAHF / SAHF: SF ZF - AF - PF - CF in AH (PF reads as 0). */
static inline void f_lahf(void)
{
    AH = (uint8_t)(cf | 0x02 | af << 4 | zf << 6 | sf << 7);
}

static inline void f_sahf(void)
{
    cf = AH & 1;
    af = (AH >> 4) & 1;
    zf = (AH >> 6) & 1;
    sf = (AH >> 7) & 1;
}

/* ------------------------------------------------------------------------ */
/* String instructions on DS:SI / ES:DI; rep = 0 (none), 1 (REP/REPE),
 * 2 (REPNE). Elements are moved one at a time, as overlapping copies and
 * fills rely on. */

static inline void str_step(uint16_t *r, int w)
{
    *r = (uint16_t)(df ? *r - w : *r + w);
}

static inline void str_movs(int w)
{
    es[DI] = ds[SI];
    if (w == 2)
        es[(uint16_t)(DI + 1)] = ds[(uint16_t)(SI + 1)];
    str_step(&SI, w);
    str_step(&DI, w);
}

static inline void str_stos(int w)
{
    if (w == 2)
        wr16(es, DI, AX);
    else
        es[DI] = AL;
    str_step(&DI, w);
}

static inline void str_lods(int w)
{
    if (w == 2)
        AX = rd16(ds, SI);
    else
        AL = ds[SI];
    str_step(&SI, w);
}

static inline void str_scas(int w)
{
    if (w == 2)
        f_sub(AX, rd16(es, DI), 0, 16);
    else
        f_sub(AL, es[DI], 0, 8);
    str_step(&DI, w);
}

static inline void str_cmps(int w)
{
    if (w == 2)
        f_sub(rd16(ds, SI), rd16(es, DI), 0, 16);
    else
        f_sub(ds[SI], es[DI], 0, 8);
    str_step(&SI, w);
    str_step(&DI, w);
}

#define STRING_OP(fn, w, rep, compares)                         \
    if (!(rep)) {                                               \
        fn(w);                                                  \
    } else {                                                    \
        while (CX != 0) {                                       \
            fn(w);                                              \
            CX--;                                               \
            if ((compares) && zf != ((rep) == 1))               \
                break;                                          \
        }                                                       \
    }

#endif
